import json,pathlib,html
P=pathlib.Path(__file__).parent
read=lambda n:(P/n).read_text(encoding='utf-8-sig')
write=lambda n,s:(P/n).write_text(s,encoding='utf-8')
d=json.loads(read('skins.json'))
# Editorial descriptors: readability, flair, motion, retro. Never performance scores.
values=[(5,3,2,1),(5,3,2,1),(5,3,2,1),(5,5,3,2),(5,4,3,1),(5,5,3,2),(5,1,2,1),(5,4,2,2),(5,4,3,1),(5,3,2,1),(5,3,1,4),(5,4,2,2),(5,4,2,4),(5,4,2,4),(4,4,1,5),(4,3,1,5),(5,3,3,2),(5,4,3,2),(4,5,1,5),(5,5,3,3),(4,5,2,5),(5,3,2,3),(5,4,3,4),(4,4,2,4),(5,4,2,3),(5,3,2,3),(5,4,3,2),(5,5,3,2),(5,3,3,1),(5,1,2,1),(5,5,3,1),(5,5,2,2),(5,2,1,5),(5,5,3,4)]
for s,v in zip(d['skins'],values):s['stats']=dict(zip(['readability','flair','motion','retro'],v))
write('skins.json',json.dumps(d,indent=2,ensure_ascii=False)+'\n')
mini=[]
for s in d['skins']:
 t=s['settings']; mini.append({k:s[k] for k in ['id','name','category','description','featured','stats']}|{'bg':t['backgroundColor'],'border':t['borderColor'],'text':t['textColor'],'nameColor':t['nameColor'],'radius':t['cornerRadius'],'font':t['fontFamily']})
write('game-catalog.js','// Review-only compact catalog; full presets remain skins.json.\nwindow.reviewSkins='+json.dumps(mini,ensure_ascii=False)+';\n')
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · ChatSkins design</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=Chakra+Petch:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="game-tokens.css"><link rel="stylesheet" href="game-menu.css"><script defer src="game-catalog.js"></script><script defer src="game-menu.js"></script></head>'''
def page(kind,title,body):
 nav=''.join(f'<a href="{file}-mockup.html"'+(' aria-current="page"' if file==kind else '')+f'>{label}</a>' for file,label in [('home','Home'),('skins','Skins'),('editor','Customize'),('request','Request')])
 shell=f'''<body data-page="{kind}"><a class="skip" href="#main">Skip to content</a><header class="topbar"><div class="wrap"><a class="brand" href="home-mockup.html"><img src="chatskins-mark.svg" alt="">ChatSkins</a><nav aria-label="Main">{nav}</nav><div class="row"><button class="utility" id="pause" aria-pressed="false">Pause motion</button></div></div></header>'''
 footer='''<footer class="wrap footer"><div class="row between"><p>Built with OpenAI Codex for the Codex x TwitchCon Hackathon</p><div class="row"><a href="https://github.com/Korivash/chatskins">GitHub</a><span>© Korivash</span></div></div><p class="review">Round 6b interactive design study. Sample chat only. Sign-in, links and quest delivery are simulated.</p></footer><dialog id="quest-dialog" aria-labelledby="quest-dialog-title"><button class="close" data-close>Close</button><h2 id="quest-dialog-title">Post a skin quest</h2><iframe title="Skin request form" data-src="request-mockup.html?embed=1"></iframe></dialog>'''
 write(kind+'-mockup.html',head.format(title=title)+shell+body+footer+'</body></html>')
def monitor(target='hero',extra=''):
 return f'''<div class="monitor"><div class="monitor-top"><strong>ChatSkins / stream monitor</strong><span>Sample chat</span></div><div class="screen"><div class="chat-sample" id="{target}-chat"></div></div>{extra}</div>'''
home='''<main id="main"><section class="attract"><div class="stars" aria-hidden="true"></div><div class="floor" aria-hidden="true"></div><div class="wrap title-screen"><div class="title-copy"><div class="mega-logo"><img src="chatskins-mark.svg" alt=""><h1>ChatSkins</h1></div><p class="tagline">Your Twitch chat. Ready to play.</p><p class="muted">Free chat skins. One link for OBS. No login needed.</p><a class="start button" href="skins-mockup.html"><span>PRESS START</span></a><nav class="menu" aria-label="Title menu"><a class="selected" href="skins-mockup.html">Start</a><a href="editor-mockup.html">Customize</a><button data-quest>Request a skin</button><a href="#obs">How to use in OBS</a><a href="#about">About</a></nav><p class="keyhint">↑ ↓ choose &nbsp; Enter select &nbsp; Space start</p></div>'''+monitor('hero','''<div class="row between"><div><p class="sample-name" id="hero-name">Bubble Lift</p><small>Featured skin · <span id="hero-count">1 / 6</span></small></div><span aria-hidden="true">✦</span></div><div class="demo-actions"><button id="previous" aria-label="Previous featured skin">←</button><a href="skins-mockup.html">Find your main</a><button id="next" aria-label="Next featured skin">→</button></div>''')+'''</div></section><div class="wrap"><section class="section" id="obs"><h2>From title screen to your stream.</h2><div class="three"><div><strong>1 / Choose your skin</strong><p>Pick a look, then choose “Use this skin”. Customize only if you want to.</p></div><div><strong>2 / Add your Twitch name</strong><p>Type your channel name and copy your overlay link. Connecting with Twitch is optional.</p></div><div><strong>3 / Add it to OBS</strong><p>Sources → + → Browser. Paste the link, set 1280 × 720, and place it above game capture. Send a chat message to test.</p></div></div></section><section class="section features" id="about"><div><h2>Your community.<br>Your signature look.</h2><p class="muted">ChatSkins dresses up the conversation already happening on your Twitch channel.</p></div><div class="feature-list"><p>34 original starting points</p><p>7TV, BTTV &amp; FFZ emotes</p><p>Transparent backgrounds</p><p>Six simple controls; a full editor</p><p>Read-only chat; never posts as you</p><p>Free to make. Free to use.</p></div></section><section class="section"><h2>Before you go live</h2><details><summary>Do I need to connect Twitch?</summary><p>No. Your channel name is enough for public chat. Optional Twitch sign-in fills it in for you.</p></details><details><summary>Can I set up while offline?</summary><p>Yes. Design with sample chat, then send a message in your Twitch chat to test your OBS source. Your stream can stay offline.</p></details><details><summary>Will it slow my stream?</summary><p>Skins use lightweight chat layers, without video backgrounds. Performance depends on your settings and computer; turn down motion if needed.</p></details><details><summary>How do I save my changes?</summary><p>Keep your overlay link, or save a skin in Advanced. After editing, copy the new link into OBS.</p></details><details><summary>What if an emote service is unavailable?</summary><p>Its emote names appear as text so the conversation stays readable.</p></details><details><summary>Can I ask for a new look?</summary><p>Absolutely. <button data-quest>Request a skin</button> Send the idea to the quest board.</p></details></section></div></main>'''
page('home','Press start',home)
quick='''<dialog id="use-dialog" aria-labelledby="use-title"><button class="close" data-close>Close</button><h2 id="use-title">Use this skin</h2><div id="use-step1"><p class="section-code">1 / Your channel</p><form id="channel-form"><label>Your Twitch name<input name="channel" id="channel" maxlength="25" required pattern="[A-Za-z0-9_]{1,25}" autocomplete="off" placeholder="cozy_channel"></label><p class="muted">Your channel name, not a Twitch URL.</p><p class="error" id="channel-error" role="status"></p><button class="primary" type="submit">Continue to link</button><button type="button" id="connect">Connect with Twitch</button><small>Optional. Sign-in is unavailable in this design study.</small></form></div><div id="use-step2" hidden><p class="section-code">2 / Copy into OBS</p><label>Example overlay link<input id="overlay-link" readonly></label><p class="notice">Design sample only. This is not a usable OBS link.</p><button class="primary" id="copy">Copy example link</button><p id="copy-status" role="status"></p><p>OBS → Sources → + → Browser. Paste your real link. Set 1280 × 720 and place it above game capture.</p><button id="back-channel">Back to channel</button></div></dialog>'''
page('skins','Choose your skin','''<main id="main" class="wrap"><div class="page-head"><span class="section-code">Skin select</span><h1>Who’s your chat today?</h1><p>Choose a look. Try it live. Take it straight to OBS.</p></div><div class="selection-layout"><section aria-label="Skin roster"><div class="tabs" role="group" aria-label="Skin groups">'''+''.join(f'<button data-group="{g}" aria-pressed="{str(i==0).lower()}">{g}</button>' for i,g in enumerate(['Streamer favorites','Game styles','Animated','Colorful']))+'''</div><p class="muted" id="roster-count" role="status"></p><div class="portraits" id="portraits"></div><p class="keyhint">Arrow keys browse · Enter or Space selects · Tab reaches actions</p><p class="notice">Missing your dream look? <button data-quest>Request a skin</button></p></section><aside class="selection-panel" aria-label="Selected skin">'''+monitor('selected')+'''<h2 id="selected-name">Bubble Lift</h2><p id="selected-description"></p><div class="stats" id="stats"></div><small>Style stats are playful descriptors, not benchmark scores.</small><div class="row" style="margin-top:20px"><button class="primary" data-use>Use this skin</button><a class="button" id="customize-link" href="editor-mockup.html?skin=bubble-lift">Customize</a></div></aside></div></main>'''+quick)
# Preserve complete previous Advanced specimen before replacing the editor.
old=read('editor-mockup.html')
if 'data-page' not in old:
 write('editor-round6-reference.html',old)
controls='''<section class="panel" aria-label="Appearance controls"><div class="row between"><h2 style="font-size:23px">Customize</h2><span>6 controls</span></div><label class="check"><input type="checkbox" id="advanced-toggle" role="switch">Advanced editor</label><div id="simple-controls"><label class="field">Font<select id="font"><option>Barlow</option><option>Nunito Sans</option><option>Georgia</option><option>monospace</option></select></label><label class="field">Text size <span class="row"><input id="size" type="range" min="12" max="48" value="22"><input id="size-number" type="number" min="12" max="48" value="22" aria-label="Text size in source pixels"></span><small>px in your OBS source</small></label><label class="field">Accent color<span class="row"><input id="accent" type="color" value="#a5f4e4"><input id="accent-hex" value="#A5F4E4" pattern="#[0-9A-Fa-f]{6}" aria-label="Accent hex color"></span><small>Names and frame accents</small></label><label class="field">Background<select id="background"><option>Solid</option><option>Glass</option><option>Transparent</option></select><small>Glass is a translucent tint in OBS.</small></label><label class="check field"><input type="checkbox" id="frame" role="switch" checked>Frame</label><label class="field">Entrance animation<select id="entrance"><option>Fade</option><option>Slide</option><option>Pop</option><option>None</option></select></label></div><div id="advanced-controls" hidden><p class="muted">Full control over every part.</p><div class="advanced">'''+''.join(f'<details><summary>{x}</summary><p>Use the retained Round 6 controls for this section, in this loadout rail.</p><a href="editor-round6-reference.html#advanced">Inspect full control inventory</a></details>' for x in ['Message box','Name','Message text','Badges','System','Panel','Frame','Background','Name format','Layout','Motion & effects','Filters & emphasis','Emotes & badges','My skins','Custom CSS'])+'''</div></div></section>'''
# Carry the complete Advanced field inventory into the new game rail.
reference=read('editor-round6-reference.html')
start=reference.index('<details ',reference.index('id="advanced"'))
end=reference.index('<div class="row"><button>Undo',start)
inventory=reference[start:end]
a=controls.index('<div class="advanced">')
controls=controls[:a]+'<p class="review">Advanced controls are visual specimens; values below illustrate Bubble Lift.</p><div class="advanced">'+inventory+'</div></div></section>'
page('editor','Customize your loadout','''<main id="main" class="wrap"><div class="page-head"><span class="section-code">Chat loadout</span><div class="row between"><h1>A little more you.</h1><button data-quest>Request a skin</button></div><p><span id="loadout-name">Bubble Lift</span> <span id="modified">/ Your starting point</span></p></div><nav class="stepbar" aria-label="Setup steps"><a href="skins-mockup.html">1 Skin</a><a href="#simple-controls" aria-current="step">2 Customize</a><button data-use>3 Get your link</button></nav><div class="loadout">'''+controls+monitor('editor','''<div class="demo-actions" role="group" aria-label="Preview background"><button data-backdrop="stream" aria-pressed="true">Stream</button><button data-backdrop="dark" aria-pressed="false">Dark</button><button data-backdrop="light" aria-pressed="false">Light</button><button data-backdrop="checker" aria-pressed="false">Checker</button></div><small>1280 × 720 source · Sample enlarged for design review</small>''')+'''<aside class="panel deploy"><span class="section-code">Ready when you are</span><h2>Get on stream.</h2><div class="slot"><strong>Equipped</strong><p id="equipped-name">Bubble Lift</p></div><p class="muted">Keep this look or tweak the six controls. Your channel is the only thing left.</p><button class="primary" data-use style="margin-top:24px;width:100%">3 Get your link</button><p class="keyhint">No login required.</p><a href="skins-mockup.html">Back to skins</a></aside></div><p class="review">Controls demonstrate appearance changes only. The full canonical settings, undo/history and Advanced field mapping remain builder work; complete Advanced specimens are retained in the linked Round 6 reference.</p></main>'''+quick)
fields=[('name','Skin name idea',60,True),('inspired','Inspired by (game/style)',80,True),('colors','Colors',80,True),('font','Font vibe',60,False),('frame','Frame idea',120,False),('description','Description',800,True),('channel','Twitch channel (optional)',25,False),('discord','Discord name (optional)',40,False)]
form=''
for n,label,limit,req in fields:
 attrs=f'name="{n}" maxlength="{limit}"'+(' required' if req else '')
 elem=f'<textarea {attrs} rows="4"></textarea>' if n=='description' else f'<input {attrs}'+(' value="#8CECE0, #C7B5FF"' if n=='colors' else '')+'>'
 form+=f'<label class="'+('wide' if n in ['colors','description','frame'] else '')+f'">{label}{elem}<small>Up to {limit} characters'+(' · required' if req else '')+'</small></label>'
 if n=='colors': form+='''<div class="row wide"><label>Primary<input type="color" id="quest-color1" value="#8cece0"></label><label>Secondary<input type="color" id="quest-color2" value="#c7b5ff"></label><small>Pick colors or describe a palette above.</small></div>'''
page('request','Post a skin quest','''<main id="main" class="wrap"><div class="quest-layout"><section><span class="section-code">Community quest board</span><h1>The next skin<br>starts with you.</h1><div class="quest-seal" aria-hidden="true">✦</div><p class="muted">A cozy tavern? A lunar arcade? Tell us what your chat should feel like. We’ll take it from here.</p><p class="notice">Requests are ideas for the guild, not guaranteed commissions. Optional contact details are shared with the team.</p><p><a href="https://discord.gg/YxFRuEPSxZ">Or join us on Discord</a></p></section><section class="panel quest-form"><h2>Post a skin quest</h2><p class="muted">Required: name, inspiration, colors and description.</p><form id="quest-form"><div class="form-grid">'''+form+'''</div><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="notice">Design study: nothing is sent. Choose an outcome to review the response.</p><label>Review outcome<select id="quest-outcome"><option value="success">Success</option><option value="invalid">Field error</option><option value="limited">Rate limited</option><option value="failed">Delivery error</option></select></label><button class="primary" type="submit" style="margin-top:20px">Post quest</button><div id="quest-status" role="status" tabindex="-1"></div></form></section></div><section class="state-specimens"><details><summary>Review all quest states</summary><p>Sending: Posting your quest… (disable repeat submissions).</p><p>Success: Quest posted! The guild has been notified.</p><p class="error">400: Check the highlighted fields. Description must be 800 characters or fewer.</p><p class="error">429: Quest board is busy. Try again in 42 minutes. Your draft is safe.</p><p class="error">503 / offline: Your quest couldn’t be delivered. Your draft is still here. Try again.</p></details></section></main>''')
print('Generated four mockups; stats added to',len(d['skins']),'skins.')
